<template><ResourceDrawer :open="visible" :title="type==='log'?'调度日志详细':'任务详细'" :width="780" @close="emit('update:visible',false)"><a-descriptions bordered :column="2" size="small"><template v-for="item in details" :key="item.label"><a-descriptions-item :label="item.label" :span="item.span||1"><template v-if="item.tag"><a-tag :color="item.color">{{item.value}}</a-tag></template><template v-else>{{item.value??'-'}}</template></a-descriptions-item></template></a-descriptions><a-card v-if="form.invokeTarget" title="调用目标" size="small" class="detail-card"><pre>{{form.invokeTarget}}</pre></a-card><a-card title="调用参数" size="small" class="detail-card"><p>位置参数：<code>{{form.jobArgs||'（无）'}}</code></p><p>关键字参数：<code>{{form.jobKwargs||'（无）'}}</code></p></a-card><a-alert v-if="type==='log'&&form.status==1" type="error" :message="form.exceptionInfo||'执行失败'" show-icon /></ResourceDrawer></template>
<script setup name="JobDetail">
import ResourceDrawer from '@/components/Antd/ResourceDrawer.vue'
import { parseTime } from '@/utils/ruoyi'
const props=defineProps({visible:{type:Boolean,default:false},row:{type:Object,default:()=>({})},type:{type:String,default:'job'}});const emit=defineEmits(['update:visible']);const form=computed(()=>props.row||{});const {proxy}=getCurrentInstance();const {sys_job_group,sys_job_executor}=proxy.useDict('sys_job_group','sys_job_executor');const label=(options,value)=>proxy.selectDictLabel(options.value,value)||'-';const costTime=computed(()=>form.value.startTime&&form.value.endTime?new Date(form.value.endTime)-new Date(form.value.startTime):0)
const details=computed(()=>props.type==='log'?[{label:'日志编号',value:form.value.jobLogId},{label:'执行状态',value:form.value.status==0?'正常':'失败',tag:true,color:form.value.status==0?'green':'red'},{label:'开始时间',value:form.value.startTime},{label:'结束时间',value:form.value.endTime},{label:'记录时间',value:form.value.createTime},{label:'执行耗时',value:`${costTime.value} 毫秒`},{label:'任务名称',value:form.value.jobName},{label:'任务分组',value:label(sys_job_group,form.value.jobGroup)},{label:'任务执行器',value:label(sys_job_executor,form.value.jobExecutor)},{label:'任务触发器',value:form.value.jobTrigger},{label:'日志信息',value:form.value.jobMessage,span:2}]:[{label:'任务编号',value:form.value.jobId},{label:'任务名称',value:form.value.jobName},{label:'任务分组',value:label(sys_job_group,form.value.jobGroup)},{label:'执行状态',value:form.value.status==0?'正常':'暂停',tag:true,color:form.value.status==0?'green':'default'},{label:'任务执行器',value:label(sys_job_executor,form.value.jobExecutor),span:2},{label:'cron 表达式',value:form.value.cronExpression},{label:'下次执行时间',value:parseTime(form.value.nextValidTime)},{label:'执行策略',value:{0:'默认策略',1:'立即执行',2:'执行一次',3:'放弃执行'}[form.value.misfirePolicy]},{label:'并发执行',value:form.value.concurrent==0?'允许':'禁止'},{label:'创建人',value:form.value.createBy},{label:'创建时间',value:form.value.createTime},{label:'更新人',value:form.value.updateBy},{label:'更新时间',value:form.value.updateTime},{label:'备注',value:form.value.remark,span:2}])
</script><style scoped>.detail-card{margin-top:16px}pre,code{white-space:pre-wrap;word-break:break-all}</style>
